mapper.select:
select count(0) from virtual_inventory vi left join virtual_warehouse vw on vi.virtual_warehouse_id = vw.id and vw.is_deleted = false
${params.sqlMap.default} and vi.is_deleted = false
${params.permissionSql}

SELECT t.indexId, t.skuId, t.virtualWarehouseId FROM ( select min(vi.id) as indexId, vi.sku_id as skuId, vi.virtual_warehouse_id as virtualWarehouseId from virtual_inventory vi left join virtual_warehouse vw on vi.virtual_warehouse_id = vw.id and vw.is_deleted = false
${params.sqlMap.default} and vi.is_deleted = false
and vi.qty != 0
${params.permissionSql}
group by vi.sku_id,vi.virtual_warehouse_id order by
${item.field} ${item.sort}
indexId )t WHERE 1=1
and t.indexId > #{lastId}
ORDER BY t.indexId

select vi.id, vi.warehouse_id, vi.sku_id, vi.dict_inventory_status, COALESCE(vi.qty,0) as virtualQty, vi.virtual_warehouse_id, (select COALESCE(sum(qty),0) from inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'usable') as usableQty, (select COALESCE(sum(qty),0) from inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'frozen') as frozenQty from virtual_inventory vi
vi.is_deleted = false and vi.sku_id in
#{item}
and vi.virtual_warehouse_id in
#{item}

select count(0) from ( select vi.sku_id,vi.warehouse_id, COALESCE(sum(vi.qty),0) as virtualQty, (select COALESCE(sum(qty),0) from inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'usable') as usableQty, (select COALESCE(sum(qty),0) from inventory where is_deleted = false and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'frozen') as frozenQty from virtual_inventory vi
vi.is_deleted = false
${params.permissionSql}
group by vi.sku_id,vi.warehouse_id ) a where virtualQty > usableQty + frozenQty;

select vi.sku_id as skuId, vi.warehouse_id as warehouseId, vi.virtual_warehouse_id as virtualWarehouseId, COALESCE(sum(vi.qty),0) as virtualQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and virtual_warehouse_id = vi.virtual_warehouse_id and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'usable') as virtualUsableQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and virtual_warehouse_id = vi.virtual_warehouse_id and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'frozen') as virtualFrozenQty from virtual_inventory vi
vi.is_deleted = false and vi.sku_id = #{params.skuId} and vi.warehouse_id = #{params.warehouseId}
${params.permissionSql}
group by vi.virtual_warehouse_id,vi.sku_id,vi.warehouse_id order by
${item.field} ${item.sort}
vi.virtual_warehouse_id

select vi.sku_id as skuId, vi.warehouse_id as warehouseId, vi.virtual_warehouse_id as virtualWarehouseId, COALESCE(sum(vi.qty),0) as virtualQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and virtual_warehouse_id = vi.virtual_warehouse_id and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'usable') as virtualUsableQty, (select COALESCE(sum(qty),0) from virtual_inventory where is_deleted = false and virtual_warehouse_id = vi.virtual_warehouse_id and sku_id = vi.sku_id and warehouse_id = vi.warehouse_id and dict_inventory_status = 'frozen') as virtualFrozenQty from virtual_inventory vi
vi.is_deleted = false and vi.sku_id in
#{item}
and vi.warehouse_id in
#{item}
group by vi.virtual_warehouse_id,vi.sku_id,vi.warehouse_id order by vi.virtual_warehouse_id

SELECT vi.warehouse_id, vi.sku_id, vi.virtual_warehouse_id as toVirtualWarehouseId, sum(case when vi.dict_inventory_status = 'usable' then vi.qty else 0 end) as toVirtualWarehouseUsableQty FROM virtual_inventory vi WHERE vi.is_deleted = FALSE and vi.sku_id in
#{skuId}
and vi.warehouse_id in
#{warehouseId}
and vi.virtual_warehouse_id in
#{virtualWarehouseId}
GROUP BY vi.warehouse_id, vi.sku_id, vi.virtual_warehouse_id

select vi.warehouse_id, vi.sku_id, sum(vi.qty) as toVirtualWarehouseRealQty from virtual_inventory vi WHERE vi.is_deleted = FALSE and vi.sku_id in
#{skuId}
and vi.warehouse_id in
#{warehouseId}
GROUP BY vi.warehouse_id, vi.sku_id

select vi.sku_id, vi.warehouse_id, vi.virtual_warehouse_id, vi.dict_inventory_status, COALESCE(sum(vi.qty),0) as inventoryQty from virtual_inventory vi
vi.is_deleted = false and vi.sku_id in
#{item}
and vi.warehouse_id in
#{item}
and vi.virtual_warehouse_id in
#{item}
and vi.dict_inventory_status = #{params.dictInventoryStatus}
group by vi.sku_id,vi.warehouse_id,vi.virtual_warehouse_id,vi.dict_inventory_status

select sum(case when vi.dict_inventory_status = 'usable' then vi.qty else 0 end)
FROM virtual_inventory vi
WHERE vi.is_deleted = FALSE

    and vi.virtual_warehouse_id =#{params.virtualWarehouseId}


    and vi.warehouse_id =#{params.warehouseId}

GROUP BY vi.virtual_warehouse_id

select COALESCE(sum(vi.qty),0) as qty from virtual_inventory vi
vi.is_deleted = false and vi.warehouse_id = #{warehouseId} and vi.sku_id = #{skuId}
group by vi.warehouse_id,vi.sku_id

select COALESCE(sum(vi.qty),0) as qty, vi.warehouse_id, vi.sku_id from virtual_inventory vi
vi.is_deleted = false and vi.warehouse_id in
#{item}
and vi.sku_id in
#{item}
group by vi.warehouse_id,vi.sku_id

select 
    from virtual_inventory
where sku_id=#{skuId} and virtual_warehouse_id=#{virtualWarehouseId}

select diff.invId, diff.sku_id,pd.sku_no as skuNo, pd.name as productName, diff.warehouse_id, wh.name as warehouseName, wh.kingdee_warehouse_code as warehouseCode, diff.usableQty, COALESCE(frozenDiff.frozenQty,0) as frozenQty, diff.usableQty + COALESCE(frozenDiff.frozenQty,0) as realQty, COALESCE(inv.usableQty,0) as distributionQty, (COALESCE(diff.usableQty,0) + COALESCE(frozenDiff.frozenQty,0) - COALESCE(inv.usableQty,0)) as unDistributionQty from (select min(vi.id) AS invId, vi.sku_id, vi.warehouse_id, sum(vi.qty) as usableQty from inventory vi where vi.is_deleted = false and vi.dict_inventory_status = 'usable' group by vi.sku_id , vi.warehouse_id) diff left join (select vi.sku_id, vi.warehouse_id, sum(vi.qty) as frozenQty from inventory vi where vi.is_deleted = false and vi.dict_inventory_status = 'frozen' group by vi.sku_id , vi.warehouse_id) frozenDiff on frozenDiff.sku_id = diff.sku_id and frozenDiff.warehouse_id = diff.warehouse_id left join ( select inv.sku_id , inv.warehouse_id ,sum(inv.qty) as usableQty from virtual_inventory inv where inv.is_deleted = false group by inv.sku_id , inv.warehouse_id ) inv on inv.sku_id = diff.sku_id and inv.warehouse_id = diff.warehouse_id left join product_detail pd on diff.sku_id = pd.id and pd.is_deleted = false left join warehouse wh on diff.warehouse_id = wh.id and wh.is_deleted = false
${params.sqlMap.default}
and COALESCE(inv.usableQty,0) > COALESCE(diff.usableQty,0) + COALESCE(frozenDiff.frozenQty,0)
and COALESCE(diff.usableQty,0) + COALESCE(frozenDiff.frozenQty,0) >= COALESCE(inv.usableQty,0)
and diff.invId > #{lastId}
ORDER BY diff.invId
